package lang

import (
	"os"
	"path/filepath"
	"testing"
)

func TestGoFuncsScanSkipsGenerated(t *testing.T) {
	dir := t.TempDir()
	files := map[string]string{
		"checks.go":      "package p\n\nfunc Positive(v int) error { return nil }\n",
		"kinds.go":       "package p\n\ntype (\n\tState string\n\tLevel = int\n\tBox[T any] string\n)\n\nfunc local() { type Inner string }\n",
		"volt_models.go": "// Code generated by volt gen from package p. DO NOT EDIT.\n\npackage p\n\ntype Hidden string\n\nfunc Generated() {}\n",
		"note.go":        "// Code generated is what this comment is about, not a marker\n\npackage p\n\nfunc Commented() {}\n",
	}
	for name, src := range files {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(src), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	for _, src := range GoSourcesRead(dir) {
		if want := src.Name == "volt_models.go"; src.Head != want {
			t.Errorf("%s read as a head: %v, want %v", src.Name, src.Head, want)
		}
	}
	funcs, gotypes, broken := GoFuncsScan(dir)
	if len(broken) != 0 {
		t.Fatalf("broken: %v", broken)
	}
	for name, want := range map[string]bool{"Positive": true, "Commented": true, "Generated": false} {
		if _, ok := funcs[name]; ok != want {
			t.Errorf("%s found=%v, want %v", name, ok, want)
		}
	}
	want := map[string]GoType{
		"State": {Underlying: "string"},
		"Level": {Underlying: "int", Alias: true},
		"Box":   {Underlying: "string", Generic: true},
	}
	if len(gotypes) != len(want) {
		t.Errorf("top-level types %v, want exactly %v (a local type and one in a generated file are invisible)", gotypes, want)
	}
	for name, w := range want {
		got, ok := gotypes[name]
		if !ok || got.Underlying != w.Underlying || got.Alias != w.Alias || got.Generic != w.Generic || got.Name != name {
			t.Errorf("type %s: %+v, want %+v", name, got, w)
		}
	}
}
